import{z as s,x as n,o as B,c as p,q as A,j as r,D as e,d as l,s as i,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"树形草稿与验证","description":"","frontmatter":{"title":"树形草稿与验证","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/spec-tree-draft-verify.md","filePath":"llm/spec-tree-draft-verify.md","lastUpdated":1791413859000}'),d={name:"llm/spec-tree-draft-verify.md"};function m(D,E,f,C,h,c){const t=n("Mermaid");return B(),p("div",null,[E[2]||(E[2]=A('<h1 id="树形草稿与验证" tabindex="-1">树形草稿与验证 <a class="header-anchor" href="#树形草稿与验证" aria-label="Permalink to &quot;树形草稿与验证&quot;">​</a></h1><div class="epigraph"><p>树不是把链画好看一点：它是把一次校验前向的节点预算，当成在深度与广度之间分配的组合问题。</p><footer>—— 据 Miao et al., SpecInfer, ASPLOS 2024 与 Cai et al., Medusa, ICML 2024 的树校验口径整理</footer></div><p><a href="/llm/spec-eagle-family">上一课</a>里树已经出现过两次：EAGLE 的静态树与置信度驱动的动态树。本课把「树形草稿与验证」本身钉成一课：链式草稿每轮只押一条路径，树形草稿一次押一片；本课写树的提议结构、校验的代数与实现、以及节点预算怎么分。链与树的接受规则同源，<a href="/llm/speculative-sampling">投机采样</a>不重证；<a href="/llm/speculative-tree">树状验证</a>给过的单孩子退化也不再展开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>链的脆弱在几何：第一个 token 被拒，右侧 \\(\\gamma-1\\) 个草稿全部作废，而这 \\(\\gamma-1\\) 步草稿前向已经付了钱。高熵位置上单路径的命中率天然低。树的直觉是广度换命中：在浅处分叉，只要有一条路径走得远就有产出。但树把账从两边同时变贵：草稿侧，节点多了提议本身要算；校验侧，一次前向要吃 \\(N\\) 个位置的 KV 与注意力，\\(N\\) 是新引入的资源。\\(N\\) 固定时，深度与广度怎么分？分错了，要么覆盖不够（退化成短链），要么验证前向白背一堆必死分支。</p><p><span class="marginnote">数字实例：\\(\\alpha=0.8\\) 时一条 4 节点路径整路命中的概率是 \\(0.8^4\\approx 41\\%\\)；\\(\\alpha=0.5\\) 时只剩 \\(0.5^4\\approx 6\\%\\)。同一棵「深 4」的树，草稿一糙，深挖基本白费——这就是深度边际收益按 \\(\\alpha^d\\) 衰减的数字含义。</span></p><p>还有一个正确性的坑：兄弟分支互不可见。掩码错成因果，分支之间互相「看见」，校验通过率虚高且分布已经漂——这不是慢，是错。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>提议</strong>。token 树最省事的来源是各位置 top-\\(s\\) 的笛卡尔积（Medusa 的头、EAGLE 的草稿分布都这么长树）；多草稿模型可以各长一棵再按置信度剪成一棵紧凑树（SpecInfer 的集体提议）。<strong>校验</strong>。把树的节点按拓扑序摆进一次前向，注意力掩码只允许每个节点看见祖先链，位置编码按树深编；目标模型一次打出全部节点的分布。<strong>接受</strong>。对每条根到叶的路径跑同一个似然比：第 \\(i\\) 个节点以 \\(\\min(1,p/q)\\) 接受，拒绝则整棵子树作废，拒绝点上从 \\(\\mathrm{norm}(\\max(0,p-q))\\) 补采一个 token——与链完全同构，只是「路径」从一条变成多条互斥候选，命中最深的那条。</p><p><strong>预算分配</strong>。节点预算 \\(N\\) 是约束，目标是最大化期望接受长度。深度的边际收益按 \\(\\alpha^d\\) 衰减：越深的节点越难被整路接受；广度的边际收益按「分叉点后的条件熵」走：低熵位置一枝就够，高熵位置值得多枝。静态树把这份分配离线定死；动态树按草稿置信度在线长（上一课的 EAGLE-2），本质是在线估计这份边际收益。</p>',10)),(B(),r(o,null,{default:e(()=>[i(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22%E6%A0%B9%EF%BC%9A%E5%B7%B2%E6%8E%A5%E5%8F%97%E5%89%8D%E7%BC%80%22%5D%20--%3E%20A%5B%22%E8%8A%82%E7%82%B9%20a%EF%BC%88top-1%EF%BC%89%22%5D%0A%20%20ROOT%20--%3E%20B%5B%22%E8%8A%82%E7%82%B9%20b%EF%BC%88top-2%EF%BC%89%22%5D%0A%20%20A%20--%3E%20A1%5B%22a1%22%5D%0A%20%20A%20--%3E%20A2%5B%22a2%22%5D%0A%20%20B%20--%3E%20B1%5B%22b1%22%5D%0A%20%20A1%20--%3E%20DEEP%5B%22%E6%9B%B4%E6%B7%B1%E8%8A%82%E7%82%B9%22%5D%0A%20%20TREE%5B%22%E5%85%A8%E9%83%A8%E8%8A%82%E7%82%B9%E4%B8%80%E6%AC%A1%E5%89%8D%E5%90%91%EF%BC%9A%E6%A0%91%E6%8E%A9%E7%A0%81%22%5D%20--%3E%20ACC%5B%22%E9%80%90%E8%B7%AF%E5%BE%84%E4%BC%BC%E7%84%B6%E6%AF%94%22%5D%0A%20%20DEEP%20--%3E%20TREE%0A%20%20A2%20--%3E%20TREE%0A%20%20B1%20--%3E%20TREE%0A%20%20ACC%20--%3E%20OUT%5B%22%E6%9C%80%E6%B7%B1%E6%8E%A5%E5%8F%97%E8%B7%AF%E5%BE%84%20%2B%20%E6%8B%92%E7%BB%9D%E7%82%B9%E8%A1%A5%E9%87%87%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[l("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"树校验合法的机制与链同一条：给定任意草稿树，因果模型在一次前向里本来就能给出每个节点的条件分布——teacher forcing 的计算图对树同样成立，掩码负责把「兄弟不可见」表达出来。树的收益机制在于互斥候选共享前缀：第一条分歧发生得越晚，被作废的节点越少，所以树的期望产出不是 \\(N\\) 的线性函数，而是强烈依赖分叉的位置结构。这也是为什么「同一个 \\(N\\)」在不同草稿质量下最优形状不同：草稿好（\\(\\alpha\\) 高）时值得深挖单枝，草稿糙时浅层多叉更划算。带宽与算力的 roofline 决定 \\(N\\) 的上界：带宽墙下 \\(N\\) 个位置的校验几乎不比一步贵；批量上来后算力接管，\\(N\\) 直接乘进 FLOPs——这条边界留给系统交互单元展开。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"树节点数 \\(N\\) 不要代进 i.i.d. 链公式当 \\(\\gamma\\) 用：链公式假设一条路径上逐位独立，树的有效深度是「被接受路径的深度」，两者只在 \\(N=\\gamma+1\\) 的单孩子退化下重合。")],-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：树掩码下兄弟节点互不可见，像同考场的人各答各的卷。掩码错成因果，等于让后面的考生偷看前面人的答案——「通过率」自然虚高，但那份成绩已经不是这份卷子的（分布漂了），这是错误不是加速。")],-1)),(B(),r(o,null,{default:e(()=>[i(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%8A%82%E7%82%B9%E9%A2%84%E7%AE%97%20N%20%E8%8A%B1%E5%9C%A8%E6%B7%B1%E8%BF%98%E6%98%AF%E5%AE%BD%3F%22%5D%20--%3E%20A%7B%22%E8%8D%89%E7%A8%BF%E8%B4%A8%E9%87%8F%20%CE%B1%20%E9%AB%98%E5%90%97%3F%22%7D%0A%20%20A%20--%3E%7C%22%E9%AB%98%3A%20%E6%95%B4%E8%B7%AF%E5%91%BD%E4%B8%AD%E6%A6%82%E7%8E%87%E5%A4%A7%22%7C%20DEEP%5B%22%E6%B7%B1%E6%8C%96%E5%8D%95%E6%9E%9D%2C%20%E8%BE%B9%E9%99%85%E6%94%B6%E7%9B%8A%20%CE%B1%5Ed%20%E8%A1%B0%E5%87%8F%E6%85%A2%22%5D%0A%20%20A%20--%3E%7C%22%E4%BD%8E%3A%20%E6%95%B4%E8%B7%AF%E5%91%BD%E4%B8%AD%E7%8E%87%E5%B0%8F%22%7C%20WIDE%5B%22%E6%B5%85%E5%B1%82%E5%A4%9A%E5%8F%89%2C%20%E5%A4%9A%E6%8A%BC%E4%BA%92%E6%96%A5%E5%80%99%E9%80%89%22%5D%0A%20%20DEEP%20--%3E%20R1%5B%22%E4%BA%A7%E5%87%BA%3A%20%E6%8E%A5%E5%8F%97%E8%B7%AF%E5%BE%84%E6%9B%B4%E9%95%BF%22%5D%0A%20%20WIDE%20--%3E%20R2%5B%22%E4%BA%A7%E5%87%BA%3A%20%E8%87%B3%E5%B0%91%E4%B8%80%E6%9E%9D%E8%B5%B0%E5%BE%97%E8%BF%9C%22%5D%0A%20%20R1%20--%3E%20B%5B%22N%20%E7%9A%84%E4%B8%8A%E7%95%8C%E7%94%B1%20roofline%20%E4%B8%8E%E6%89%B9%E9%87%8F%E5%AE%9A%22%5D%0A%20%20R2%20--%3E%20B%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>树掩码与接受路径必须逐位一致，这是实现里最容易静默出错的地方。动态树的置信度代理依赖校准，换接受规则即失效（上一课的边界在这里仍然成立）。树宽在批处理下的收益递减，Medusa 的树在单请求与并发服务里不是同一个最优。typical acceptance 一类放宽让「路径接受」脱离似然比，树形结构还在，无损声明没了。多草稿合树的编排成本（多份草稿 KV、剪枝同步）在分布式里放大，SpecInfer 的数字钉在它的编排方式上，不是树本身给的。</p><p><span class="marginnote">常见误区：以为树越宽越保险。宽出的节点都挤进同一次校验前向占座位——低熵位置第一枝几乎必中，多叉只是给 KV 与注意力白添开销。宽要花在高熵分叉点上，不是均匀撒。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>链每轮押一条路径，树押一片：浅处分叉换命中，代价是节点预算 \\(N\\) 成为新资源。</li><li>校验 = 树掩码 + 一次前向打全部节点分布；接受 = 逐路径似然比，拒绝废子树、拒绝点补采。</li><li>预算分配：深度边际收益按 \\(\\alpha^d\\) 衰减，广度按分叉点条件熵走；动态树是在线估计这份分配。</li><li>树掩码错成因果掩码是正确性事故：分支互相可见，通过率虚高、分布漂移。</li><li>\\(N\\) 不等于 \\(\\gamma\\)，i.i.d. 链公式不能直接套树。</li><li>出处：Miao et al., <em>SpecInfer</em>, ASPLOS 2024；Cai et al., <em>Medusa</em>, ICML 2024；Li et al., <em>EAGLE-2</em>, EMNLP 2024。</li></ul>',5))])}const g=s(d,[["render",m]]);export{F as __pageData,g as default};
